def title_of(html: str) -> str:
    """Return the text between the first <title> and </title> in html.

    The html string is already fetched; this function must not use the network.
    Returns an empty string when no title element is present.
    """
    open_tag = "<title>"
    close_tag = "</title>"
    start = html.find(open_tag)
    if start == -1:
        return ""
    start += len(open_tag)
    end = html.find(close_tag, start)
    if end == -1:
        return ""
    return html[start:end]


def test_title_of_simple() -> None:
    assert title_of("<html><head><title>Hello</title></head></html>") == "Hello"


def test_title_of_missing_returns_empty() -> None:
    assert title_of("<html><body>no title here</body></html>") == ""


def test_title_of_empty_input_returns_empty() -> None:
    assert title_of("") == ""


def test_title_of_uses_first_title() -> None:
    assert title_of("<title>First</title><title>Second</title>") == "First"


def test_title_of_preserves_inner_whitespace() -> None:
    assert title_of("<title>  Spaced out  </title>") == "  Spaced out  "
